// Entirely synthetic public-search response and rendered cards; no real shop captures.
export function regioFixture(count=2,availability='in stock'){
  const documents=Array.from({length:count},(_,index)=>({document:{identifier:String(101+index).padStart(5,'0'),displayText:'Pokémon Demo '+(index+1),url:`https://www.regiojatek.hu/termek-${String(101+index).padStart(5,'0')}-pokemon-demo.html`,imageUrl:`https://www.regiojatek.hu/data/regio_images/data/regio_images/preview/${String(101+index).padStart(5,'0')}_0.webp`,price:'2 995',priceValue:2995,availability,category:'Kártya',termekazonosito:String(9001+index)}}));
  const escape=(text:string)=>text.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');
  const cards=documents.map(({document:d})=>`<div class="prefixbox-product-container"><a href="${d.url}"></a><div data-product-info="${escape(JSON.stringify(d))}"><div class="pfbx-product-img"><img src="${d.imageUrl}"></div><p class="pfbx-product-name">${d.displayText}</p><div class="product-box-bottom">2 995 Ft</div><div class="prefixbox-product-cart-container">${availability==='in stock'?`<a href="#" class="add-to-cart" data-cart-product-id="${d.termekazonosito}" data-cart-product-no="${d.identifier}" data-cart-product-name="${d.displayText}">Kosárba</a>`:`<a href="${d.url}">Részletek</a>`}</div></div></div>`);
  const api={documents,count,pageSize:30,resultStatus:'resultFound',resultCount:count,resultPerPage:30,searchParameters:{query:'pokemon',page:1,resultsPerPage:30,filters:{rangeFilters:[],termFilters:[{name:'category',values:['Kártya']}],geoDistanceFilters:[]}},responseDescriptor:{responseStatus:{responseStatusCode:0},errors:[]}};
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>REGIO JÁTÉK</title></head><body><div id="prefixbox-res-counter-box-container"><div class="prefixbox-result-text">${count} termék</div></div><div id="prefixbox-app-container">${cards.map(card=>`<div class="prefixbox-product-container-wrapper">${card}</div>`).join('')}</div><div id="paginator"></div></body></html>`;
  return {api,html,cards};
}
